package com.ridex.location.config;
import org.junit.jupiter.api.Test; import org.springframework.data.redis.connection.RedisConnectionFactory; import org.springframework.data.redis.cache.RedisCacheManager; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class CacheConfigTest { @Test void createsCacheManagerWithNearbyDriversCache(){RedisConnectionFactory factory=mock(RedisConnectionFactory.class);RedisCacheManager manager=new CacheConfig(new LocationCacheErrorHandler()).cacheManager(factory);assertNotNull(manager.getCache("nearbyDrivers"));assertNotNull(manager.getCache("otherCache"));assertTrue(manager.getCacheNames().contains("nearbyDrivers"));} @Test void exposesConfiguredErrorHandler(){LocationCacheErrorHandler handler=new LocationCacheErrorHandler();assertSame(handler,new CacheConfig(handler).errorHandler());} }
